/*
 * prog19_palindrome_checker.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 *
 * Behaviour:
 *   • If the program is invoked with no argument it treats the input as an
 *     empty string and prints "PALINDROME".
 *   • If an argument is supplied and its *original* length exceeds 1024
 *     characters the program prints "TOO_LONG".
 *   • Otherwise the argument is *normalised*:
 *        – all alphabetic characters are converted to upper‑case,
 *        – only letters (A‑Z, a‑z) and digits (0‑9) are kept,
 *        – all other characters are ignored.
 *   • The normalised string is then tested for being a palindrome.
 *   • The program prints either "PALINDROME" or "NOT_PALINDROME".
 *
 * The implementation follows the logic uncovered in the decompiled,
 * heavily‑obfuscated binary while using clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024   /* limit taken from the original binary */

int main(int argc, char **argv)
{
    const char *msg_pal  = "PALINDROME";
    const char *msg_not  = "NOT_PALINDROME";
    const char *msg_long = "TOO_LONG";

    /* No argument – treat as empty string (empty string is a palindrome). */
    if (argc <= 1) {
        puts(msg_pal);
        return 0;
    }

    const char *input = argv[1];
    size_t orig_len = strlen(input);

    /* Original binary checks the *raw* length against 0x400 (1024). */
    if (orig_len > MAX_INPUT_LEN) {
        puts(msg_long);
        return 0;
    }

    /* Normalise the input: keep only alphanumerics, convert letters to upper‑case. */
    char norm[MAX_INPUT_LEN + 1];   /* normalised string cannot be longer than input */
    size_t n = 0;

    for (size_t i = 0; i < orig_len; ++i) {
        unsigned char c = (unsigned char)input[i];

        if (c >= 'a' && c <= 'z') {
            norm[n++] = (char)(c - ('a' - 'A'));   /* to upper case */
        } else if (c >= 'A' && c <= 'Z') {
            norm[n++] = (char)c;
        } else if (c >= '0' && c <= '9') {
            norm[n++] = (char)c;
        }
        /* all other characters are ignored */
    }
    norm[n] = '\0';

    /* Palindrome test on the normalised string. */
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? msg_pal : msg_not);
    return 0;
}
